def ts():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def log(level, msg):
    spaces = "  " if level in ("WARN","INFO") else " "
    sys.stderr.write(f"{ts()} [{level}]{spaces}{msg}\n")

def load_help(name):
    for p in [pathlib.Path(f"help_{name}.txt"), pathlib.Path(f"/tmp/precise_{name}.txt")]:
        if p.exists():
            return p.read_text()
    return ""

HELP = {
    "": load_help("main"),
    "main": load_help("main"),
    "init": load_help("init"),
    "diff": load_help("diff"),
    "push": load_help("push"),
    "pull": load_help("pull"),
    "format": load_help("format"),
    "lint": load_help("lint"),
    "add-environment": load_help("add-environment"),
    "help": load_help("help"),
    "version": load_help("version"),
}
VALID = ["add-environment","diff","format","help","init","lint","pull","push","version"]

